import {escapeHtml as esc,icon,formatDate} from '../ui.js';
import {deviceCatalog,searchCatalog,catalogCategories} from '../connections/catalog.js';
import {productMediaById} from '../connections/product-media.js';

const galleryOrder=['omron-complete-bp7900','alivecor-kardiamobile-6l','wellue-o2ring','withings-body-smart','dexcom-g7','withings-scanwatch-2','withings-thermo','polar-h10-heart-rate'];
const galleryRank=entry=>entry.manufacturer==='Bluetooth standard'?1000:galleryOrder.includes(entry.id)?galleryOrder.indexOf(entry.id):100;
const catalogName=entry=>entry.name||`${entry.manufacturer} ${entry.model}`;
const categoryName=value=>String(value).replaceAll('_',' ').replaceAll('-',' ').replace(/\b\w/g,char=>char.toUpperCase());
const categoryLabel=entry=>catalogCategories.find(item=>item.id===entry.category)?.label||categoryName(entry.category);
const mediaFor=entry=>productMediaById[entry.id]||{shortType:categoryLabel(entry),summary:categoryLabel(entry),imageSrc:null};
function productPhoto(entry,{large=false}={}){
  const media=mediaFor(entry);
  return `<figure class="product-photo ${large?'product-photo-large':''} ${media.imageSrc?'':'product-photo-fallback'}">${media.imageSrc?`<img src="${esc(media.imageSrc)}" alt="${esc(media.imageAlt||catalogName(entry))}" width="${large?180:112}" height="${large?150:96}" loading="lazy" decoding="async">`:`${icon(entry.category==='heart-rate'||entry.category==='ecg'?'heart':'connect',large?34:28)}<figcaption>${entry.manufacturer==='Bluetooth standard'?'Device type':'Photo unavailable'}</figcaption>`}</figure>`;
}
const time=value=>value?`${formatDate(value,{short:true,time:true})}, ${new Date(value).getFullYear()}`:'Not available';

function streamPanel(ctx) {
  const bt=ctx.connectionUI.bluetooth;
  const sample=bt.latestSample;
  const value=sample?.bpm;
  const profile=sample?.kind||bt.profile;
  const numeric=value=>Number.isFinite(value)?Number(value).toLocaleString('en-US',{maximumFractionDigits:1}):'—';
  const reading=profile==='blood_pressure'?`${numeric(sample?.systolic)} / ${numeric(sample?.diastolic)}`:profile==='pulse_oximeter'?numeric(sample?.spo2):numeric(value);
  const unit=profile==='blood_pressure'?(sample?.unit||'mmHg'):profile==='pulse_oximeter'?'%':profile==='heart_rate'?'bpm':'';
  const label=profile==='blood_pressure'?'Blood pressure':profile==='pulse_oximeter'?'Oxygen saturation':profile==='heart_rate'?'Live heart rate':'Device reading';
  const samples=bt.samples||[];
  const receiving=bt.status==='receiving';
  const hasSession=Boolean(bt.device||sample||['connecting','waiting','receiving'].includes(bt.status));
  return `<section class="bluetooth-panel ${hasSession?'has-session':'is-idle'}" aria-labelledby="bluetooth-title"><div class="bluetooth-intro"><span class="connection-symbol">${icon('connect',20)}</span><div><h2 id="bluetooth-title">Bluetooth measurements</h2><p>Connect a compatible nearby health monitor.</p></div></div><div class="bluetooth-session">${hasSession?`<div class="live-reading"><span>${bt.latestSampleStale?(['unusable_measurement','invalid_measurement'].includes(bt.errorCode)?'Previous reading · Latest measurement rejected':'Previous reading · Disconnected'):esc(label)}</span><strong class="${profile==='blood_pressure'?'pressure-reading':''}">${esc(reading)} <small>${esc(unit)}</small></strong><span>${bt.device?esc(bt.device.name||'Selected health monitor'):'Choose your nearby health monitor'}</span></div>`:''}<div class="bluetooth-status"><span class="connection-status ${receiving?'is-receiving':''}">${esc(categoryName(bt.status))}</span>${!hasSession&&bt.status==='available'?'':`<p id="bluetooth-message" role="status">${esc(bt.message||'Choose a nearby monitor to start.')}</p>`}${(sample?.qualityWarnings||[]).map(warning=>`<p class="sensor-note">${esc(warning)}</p>`).join('')}${sample?.pulseRate!=null?`<p>Pulse: ${numeric(sample.pulseRate)} bpm</p>`:''}${sample?.contactDetected===false?'<p class="sensor-note">Sensor contact was not detected. Check the fit before using this reading.</p>':''}${bt.latestSample?`<p class="muted">Latest reading: ${esc(time(bt.latestSample.timestamp||bt.latestSample.observedAt))} · ${samples.length} retained readings${bt.totalSamples>samples.length?` of ${bt.totalSamples} received`:""}</p>`:''}<div class="button-row">${bt.connected?'<button class="button" data-bluetooth-disconnect>Disconnect</button>':`<button class="button primary" data-bluetooth-connect ${!bt.available||bt.status==='connecting'?'disabled':''}>${bt.status==='connecting'?'Connecting…':'Find nearby monitors'} ${icon('connect',16)}</button>`}${samples.length?`<button class="button" data-bluetooth-download>Download readings</button>${ctx.workspace.mode==='local'?`<button class="button primary" id="save-device-readings" data-save-device-readings ${ctx.journalUI?.savingDevice?'disabled':''}>${ctx.journalUI?.savingDevice?'Saving…':'Save readings'}</button>`:''}`:''}${ctx.workspace.deviceReadings?.length?'<button class="button" data-view-device-readings>View saved readings</button>':''}</div></div></div>${!hasSession?'<details class="pairing-help"><summary>Device and storage details</summary>':''}<p class="connection-footnote">Supports standard heart-rate, blood-pressure and pulse-oximeter services. ${ctx.workspace.mode==='local'?'Save readings to keep them in your local database after closing this page.':'Readings stay in this browser session. Open the local workspace to save them.'} Compatibility depends on the device and browser. ${!bt.available?'Open this page in Chrome or Edge on a supported computer, or Chrome on Android, to pair.':'Keep the monitor awake and nearby.'}</p>${!hasSession?'</details>':''}</section>`;
}

function connectedSources(ctx) {
  const local=ctx.workspace.mode==='local';
  return `<section class="connected-history" aria-labelledby="connected-history-title"><div class="section-title"><div><h2 id="connected-history-title">Your connected history</h2><p class="muted">${local?'Read from the history already synchronized by your Health app.':'Connect your local Health app to bring Google Health and Lyfta history into this workspace.'}</p></div>${local?`<button class="button" data-refresh-workspace ${ctx.connectionUI.refreshing?'disabled':''}>${icon('reset',15)}${ctx.connectionUI.refreshing?'Refreshing…':'Refresh history'}</button>`:'<a class="button" href="http://127.0.0.1:4173/?screen=connect">Open local workspace '+icon('arrow',16)+'</a>'}</div><div class="connected-source-list">${['google-health','lyfta'].map(id=>{
    const source=ctx.sources.find(item=>item.id===id),available=source?.status==='connected';
    const records=ctx.workspace.events.filter(event=>event.sourceId===id).length;
    const workouts=id==='lyfta'?ctx.workspace.workouts.length:0;
    return `<article class="connected-source-row"><span class="registry-icon">${icon(id==='lyfta'?'activity':'source',25)}</span><div class="connected-source-copy"><h3>${id==='lyfta'?'Lyfta':'Google Health'}</h3><p class="muted">${esc(source?.description||(id==='lyfta'?'Your saved workouts, exercises and completed sets.':'Your synchronized sleep, steps and resting heart rate.'))}</p><span class="connection-status">${available?'Local history connected':'Not connected here'}</span>${available?`<small>Last sync: ${esc(time(source.lastSyncedAt))}</small>`:''}</div><div class="connected-source-action">${available?`<strong>${id==='lyfta'?workouts:records} ${id==='lyfta'?'workouts':'daily measurements'}</strong><button class="button" data-view-source="${id}">View ${id==='lyfta'?'workouts':'records'} ${icon('arrow',16)}</button>`:'<a class="button" href="http://localhost:3000" target="_blank" rel="noopener noreferrer">Set up in Health app '+icon('arrow',16)+'</a>'}</div></article>`;
  }).join('')}</div><div class="local-records-summary">${local?`<span>Local journal: ${ctx.workspace.events.filter(event=>event.sourceId==='checkins').length} check-ins · ${ctx.workspace.deviceReadings?.length||0} device readings</span><button class="button" data-screen="overview">Add check-in</button>${ctx.workspace.deviceReadings?.length?'<button class="button" data-view-device-readings>Saved device readings</button>':''}`:''}</div><p class="connection-footnote">${local?'Refresh reads the latest saved history. Manage account authorization and synchronization in your existing Health app.':'Your personal history stays on your computer. The public website does not publish or share it.'} <a href="http://localhost:3000" target="_blank" rel="noopener noreferrer">Open Health app</a></p>${ctx.workspace.notices?.length?`<details class="history-method"><summary>How your history is read</summary>${ctx.workspace.notices.map(note=>`<p class="connection-notice">${esc(typeof note==='string'?note:note.message||'')}</p>`).join('')}</details>`:''}</section>`;
}

function deviceDetails(entry,ctx) {
  if(!entry)return '';
  const tryProfile={'heart-rate':'heart_rate','blood-pressure':'blood_pressure','pulse-oximeter':'pulse_oximeter'}[entry.category];
  const media=mediaFor(entry);
  const steps=Array.isArray(entry.setup)?entry.setup:[entry.setup].filter(Boolean);
  return `<section class="device-detail panel" id="device-detail" tabindex="-1" aria-labelledby="device-detail-title"><div class="section-title device-detail-heading">${productPhoto(entry,{large:true})}<div class="device-detail-identity"><span class="device-manufacturer">${esc(entry.manufacturer)}</span><h2 id="device-detail-title">${esc(catalogName(entry))}</h2><p class="device-type">${esc(media.shortType)}</p><p class="device-definition">${esc(media.summary)}</p></div><button class="button subtle" data-device-close aria-label="Close device details">${icon('close',18)}</button></div><span class="connection-status">${esc(categoryName(entry.supportStatus||entry.connectionMethod))}</span><p>${esc(entry.description)}</p>${steps.length?`<ol class="device-setup">${steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol>`:''}<div class="button-row">${entry.canConnect?`<button class="button primary" data-bluetooth-connect="${esc(entry.id)}" ${!ctx.connectionUI.bluetooth.available||ctx.connectionUI.bluetooth.status==='connecting'?'disabled':''}>Find compatible device ${icon('connect',16)}</button>`:tryProfile?`<button class="button" data-bluetooth-profile="${tryProfile}" ${!ctx.connectionUI.bluetooth.available?'disabled':''}>Check Bluetooth support ${icon('connect',16)}</button>`:''}${entry.manufacturerUrl?`<a class="button" href="${esc(entry.manufacturerUrl)}" target="_blank" rel="noopener noreferrer">Manufacturer setup ${icon('arrow',16)}</a>`:''}</div><p class="connection-footnote">${entry.canConnect?'The browser chooser filters by the advertised measurement service. A catalog listing does not verify this exact model or firmware.':tryProfile?'A product-specific integration is not implemented. Check Bluetooth support to see whether your device advertises the standard measurement service; if it does not appear, use the manufacturer’s setup.':'This connection method needs its own integration. Selecting this product does not pair it or import measurements.'}</p></section>`;
}

export async function renderConnect(ctx) {
  const ui=ctx.connectionUI;
  const results=searchCatalog(ui.query,{category:ui.category==='all'?undefined:ui.category}).sort((a,b)=>galleryRank(a)-galleryRank(b));
  const categories=[...new Set(deviceCatalog.map(entry=>entry.category))];
  const selected=deviceCatalog.find(entry=>entry.id===ui.selectedDevice);
  return `<div class="connections-workspace"><section class="device-library" aria-labelledby="device-library-title"><div class="section-title"><div><h2 id="device-library-title">Device catalog</h2><p class="muted">Search a brand, model, or measurement. See how it can connect before you start.</p></div><span class="pill">${deviceCatalog.length} connection guides</span></div><label class="catalog-search-label" for="device-search">Device or manufacturer</label><div class="catalog-search"><span>${icon('connect',20)}</span><input type="search" id="device-search" autocomplete="off" placeholder="Try Polar H10, Kardia, ECG…" value="${esc(ui.query)}" aria-controls="device-results"></div><div class="catalog-categories" role="group" aria-label="Device category">${['all',...categories].map(category=>`<button class="${ui.category===category?'selected':''}" data-device-category="${esc(category)}" aria-pressed="${ui.category===category}">${esc(catalogCategories.find(item=>item.id===category)?.label||categoryName(category))}</button>`).join('')}</div>${deviceDetails(selected,ctx)}<p id="device-result-count" class="muted" aria-live="polite">${results.length} ${results.length===1?'match':'matches'}${ui.query?` for “${esc(ui.query)}”`:''}</p><div class="device-results" id="device-results" role="region" aria-label="Device catalog results" tabindex="0">${results.length?results.map(entry=>`<article class="device-row">${productPhoto(entry)}<div class="device-copy"><h3>${esc(catalogName(entry))}</h3><span class="device-type">${esc(mediaFor(entry).shortType)}</span><p class="device-definition">${esc(mediaFor(entry).summary)}</p><span class="device-method">${esc(entry.supportStatus)}</span></div><button class="button" data-device-id="${esc(entry.id)}" aria-label="View connection details for ${esc(catalogName(entry))}">Details ${icon('arrow',16)}</button></article>`).join(''):'<div class="catalog-empty"><h3>No matching device yet.</h3><p>Try the manufacturer name or a measurement such as ECG. A device that broadcasts the standard Heart Rate service can still appear through Pair nearby.</p><button class="button" data-device-clear>Clear search</button></div>'}</div><p class="connection-footnote">This is a curated compatibility catalog, not a list of devices detected nearby. Proprietary ECG, glucose, and other device protocols require their own supported integration.</p></section>${connectedSources(ctx)}${streamPanel(ctx)}</div>`;
}
